import java.io.BufferedInputStream;
import java.util.StringJoiner;

public class Main {

    // 计算一组数据的答案
    public static long[] solveCase(int n, int[] a) {
        // ans[i] 表示第 i 个位置作为中位数的连续子区间个数
        long[] ans = new long[n];

        // 贡献和范围为 [-n, n]
        int offset = n + 2;
        int size = 2 * n + 5;

        // 枚举每个位置作为中心
        for (int i = 0; i < n; i++) {
            int[] cnt = new int[size];

            // 左侧为空，贡献和为 0
            cnt[offset] = 1;

            // 从 i-1 向左枚举，统计左侧贡献和出现次数
            int cur = 0;
            for (int l = i - 1; l >= 0; l--) {
                if (a[l] < a[i]) {
                    cur++;
                } else {
                    cur--;
                }
                cnt[cur + offset]++;
            }

            // 从 i 开始向右枚举，r=i 表示右侧为空
            cur = 0;
            for (int r = i; r < n; r++) {
                if (r > i) {
                    if (a[r] < a[i]) {
                        cur++;
                    } else {
                        cur--;
                    }
                }

                // 统计满足 left_sum + cur == 0 或 1 的方案数
                ans[i] += cnt[-cur + offset];
                ans[i] += cnt[1 - cur + offset];
            }
        }

        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int T = fs.nextInt();
        StringBuilder sb = new StringBuilder();

        while (T-- > 0) {
            int n = fs.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = fs.nextInt();
            }

            long[] ans = solveCase(n, a);

            StringJoiner sj = new StringJoiner(" ");
            for (int i = 0; i < n; i++) {
                sj.add(String.valueOf(ans[i]));
            }
            sb.append(sj).append('\n');
        }

        System.out.print(sb.toString());
    }

    // 题目数据范围不大，使用普通输入方式即可
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws Exception {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int nextInt() throws Exception {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
